#include <bits/stdc++.h>
using namespace std;

const int N = 200005;
const int INF = 1e9+7;

long long t[4*N], lazy[4*N];
int n;

void build(int v, int tl, int tr, const vector<long long>& a) {
    if (tl == tr) {
        t[v] = a[tl];
    } else {
        int tm = (tl + tr)/2;
        build(v*2, tl, tm, a);
        build(v*2+1, tm+1, tr, a);
        t[v] = min(t[v*2], t[v*2+1]);
    }
}

void push(int v, int tl, int tr) {
    if (lazy[v] != 0) {
        t[v] += lazy[v];
        if (tl != tr) {
            lazy[v*2] += lazy[v];
            lazy[v*2+1] += lazy[v];
        }
        lazy[v] = 0;
    }
}

void update(int v, int tl, int tr, int l, int r, long long add) {
    push(v, tl, tr);
    if (l > r) return;
    if (l == tl && r == tr) {
        lazy[v] += add;
        push(v, tl, tr);
    } else {
        int tm = (tl + tr)/2;
        update(v*2, tl, tm, l, min(r, tm), add);
        update(v*2+1, tm+1, tr, max(l, tm+1), r, add);
        t[v] = min(t[v*2], t[v*2+1]);
    }
}

long long query(int v, int tl, int tr, int l, int r) {
    push(v, tl, tr);
    if (l > r) return INF;
    if (l == tl && r == tr) {
        return t[v];
    }
    int tm = (tl + tr)/2;
    return min(query(v*2, tl, tm, l, min(r, tm)),
               query(v*2+1, tm+1, tr, max(l, tm+1), r));
}

