#include <bits/stdc++.h>
using namespace std;
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M; cin >> N >> M;
    const int INF = 1e9;
    vector<vector<int>> g(N+1);
    vector<int> dist(N+1, INF);
    dist[1] = 0;

    for(int i=0;i<M;i++){
        int t; cin >> t;
        if(t==1){
            int x; cin >> x;
            if(dist[x]==INF) cout << -1 << '\n';
            else cout << dist[x] << '\n';
        } else {
            int u,v; cin >> u >> v;
            g[u].push_back(v);
            if(dist[u]!=INF && dist[v] > dist[u]+1){
                dist[v] = dist[u]+1;
                queue<int> q; q.push(v);
                while(!q.empty()){
                    int cur = q.front(); q.pop();
                    for(int to : g[cur]){
                        if(dist[to] > dist[cur] + 1){
                            dist[to] = dist[cur] + 1;
                            q.push(to);
                        }
                    }
                }
            }
        }
    }
    return 0;
}

