#include <bits/stdc++.h>
using namespace std;
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int m;
    if(!(cin >> m)) return 0;
    unordered_map<string,int> id;
    vector<string> names;
    vector<pair<int,int>> edges;
    names.reserve(2*m);

    for(int i=0;i<m;i++){
        string a,b; cin >> a >> b;
        if(!id.count(a)){ id[a]=names.size(); names.push_back(a); }
        if(!id.count(b)){ id[b]=names.size(); names.push_back(b); }
        int ia=id[a], ib=id[b];
        edges.emplace_back(ia,ib);
    }

    int n = names.size();
    vector<vector<int>> adj(n);
    for(auto &e: edges){
        adj[e.first].push_back(e.second);
        adj[e.second].push_back(e.first);
    }

    cout << n << '\n';

    vector<int> cnt(n);
    vector<int> touched;
    vector<char> marked(n);

    for(int x=0;x<n;x++){
        // mark x and x's mates
        marked[x]=1; touched.push_back(x);
        for(int v: adj[x]){ if(!marked[v]){ marked[v]=1; touched.push_back(v); } }

        int mx = 0;
        vector<int> local_touched;
        for(int v: adj[x]){
            for(int w: adj[v]){
                if(marked[w]) continue; // either x itself or already a mate
                if(cnt[w]==0) local_touched.push_back(w);
                cnt[w]++;
                mx = max(mx, cnt[w]);
